const PHRASES=[{"en":"hope for","ja":"～を望む・期待する","lv":1,"ty":"動詞句","ex":"The farmers are hoping for rain because the fields are very dry.","parts":["hoping for"],"exj":"畑がとても乾いているので、農家の人たちは雨を望んでいる。","tip":"hope for＋名詞。hope to＋動詞の原形","ans":true,"dis":["turn off","show off","major in","apply for","belong to"],"set":0,"id":"p0"},{"en":"after a while","ja":"しばらくして","lv":1,"ty":"前置詞句・副詞句","ex":"The baby cried at first, but after a while she fell asleep.","parts":["after a while"],"exj":"赤ちゃんは最初泣いていたが、しばらくして眠った。","tip":"a while＝しばらくの間。for a while＝しばらくの間","ans":true,"dis":["for long","in advance","on business","up to date","in common"],"set":0,"id":"p1"},{"en":"by mistake","ja":"間違って・うっかり","lv":1,"ty":"前置詞句・副詞句","ex":"I sent the message to my teacher by mistake, not to my friend.","parts":["by mistake"],"exj":"私は友達ではなく先生に、間違ってメッセージを送った。","tip":"on purpose（わざと）の反対","ans":true,"dis":["for long","in common","in good shape","in line","out of the question"],"set":0,"id":"p2"},{"en":"feel like","ja":"～したい気がする","lv":1,"ty":"動詞句","ex":"It is so hot today that I feel like eating ice cream.","parts":["feel like"],"exj":"今日はとても暑いので、アイスクリームが食べたい。","tip":"feel like ～ing。後ろは動名詞","ans":true,"dis":["look like","turn off","belong to","apply for","run over"],"set":0,"id":"p3"},{"en":"look like","ja":"～に似ている・～のようだ","lv":1,"ty":"動詞句","ex":"You look like your mother when you smile.","parts":["look like"],"exj":"あなたは笑うとお母さんに似ている。","tip":"look like ＋名詞。look happy（形容詞）と区別","ans":false,"dis":["turn off","hope for","apply for","major in","give off"],"set":0,"id":"p4"},{"en":"and so on","ja":"～など","lv":1,"ty":"その他","ex":"At the market, we bought apples, bananas, oranges, and so on.","parts":["and so on"],"exj":"市場でリンゴ、バナナ、オレンジなどを買った。","tip":"＝and so forth／etc. 例を並べた最後に置く","ans":true,"dis":["for long","in a minute","in common","in a word","every other"],"set":0,"id":"p5"},{"en":"for long","ja":"長い間","lv":1,"ty":"前置詞句・副詞句","ex":"I can't stay for long because I have to be home by six.","parts":["for long"],"exj":"6時までに帰らないといけないので、長くはいられない。","tip":"主に否定文・疑問文で使う","ans":false,"dis":["by mistake","by heart","in common","out of date","up to date"],"set":0,"id":"p6"},{"en":"at least","ja":"少なくとも","lv":1,"ty":"前置詞句・副詞句","ex":"You should sleep at least seven hours the night before a test.","parts":["at least"],"exj":"テストの前の晩は少なくとも7時間は寝るべきだ。","tip":"at most（多くても）と反対の意味","ans":false,"dis":["by mistake","for long","on business","in common","out of date"],"set":0,"id":"p7"},{"en":"turn off","ja":"～を消す・止める","lv":1,"ty":"動詞句","ex":"Please turn off the lights when you leave the room.","parts":["turn off"],"exj":"部屋を出るときは電気を消してください。","tip":"反対は turn on（つける）","ans":false,"dis":["hope for","look like","agree with","major in","apply for"],"set":0,"id":"p8"},{"en":"be busy with","ja":"～で忙しい","lv":1,"ty":"動詞句","ex":"My mother is busy with work, so I cook dinner on weekdays.","parts":["busy with"],"exj":"母は仕事で忙しいので、平日は私が夕食を作る。","tip":"be busy ～ing＝～するのに忙しい","ans":false,"dis":["be made up of","be on the point of","hope for","belong to","major in"],"set":0,"id":"p9"},{"en":"give up","ja":"あきらめる・～をやめる","lv":1,"ty":"動詞句","ex":"Don't give up. You can finish the race if you keep running.","parts":["give up"],"exj":"あきらめないで。走り続ければ完走できるよ。","tip":"give up ～ing＝～するのをやめる","ans":false,"dis":["grow up","shake hands","come true","dress up","major in"],"set":1,"id":"p10"},{"en":"calm down","ja":"落ち着く・～を落ち着かせる","lv":1,"ty":"動詞句","ex":"Take a deep breath and calm down before your speech.","parts":["calm down"],"exj":"スピーチの前に深呼吸して落ち着きなさい。","tip":"Calm down!＝落ち着いて！ calm＝穏やかな","ans":false,"dis":["grow up","come true","break out","take place","give way"],"set":1,"id":"p11"},{"en":"come true","ja":"（夢などが）実現する","lv":1,"ty":"動詞句","ex":"She practiced hard every day, and her dream of winning finally came true.","parts":["came true"],"exj":"彼女は毎日必死に練習し、優勝の夢がついにかなった。","tip":"A dream comes true. の形で覚える","ans":true,"dis":["shake hands","calm down","grow up","dress up","sit up"],"set":1,"id":"p12"},{"en":"depend on","ja":"～次第である・～に頼る","lv":1,"ty":"動詞句","ex":"The price of the tour depends on how many people join it.","parts":["depends on"],"exj":"ツアーの値段は参加する人数によって決まる。","tip":"It depends.＝場合によるよ","ans":true,"dis":["agree with","give up","calm down","belong to","major in"],"set":1,"id":"p13"},{"en":"be filled with","ja":"～でいっぱいである","lv":1,"ty":"動詞句","ex":"The stadium was filled with fans wearing blue shirts.","parts":["filled with"],"exj":"スタジアムは青いシャツを着たファンでいっぱいだった。","tip":"＝be full of","ans":false,"dis":["be on the point of","agree with","calm down","depend on","give up"],"set":1,"id":"p14"},{"en":"agree with","ja":"～（人・意見）に賛成する","lv":1,"ty":"動詞句","ex":"Ken said we should leave early, and I agree with him.","parts":["agree with"],"exj":"ケンは早く出発すべきだと言い、私も彼に賛成だ。","tip":"agree with＋人・意見。agree to＋提案","ans":false,"dis":["come true","grow up","run over","major in","give off"],"set":1,"id":"p15"},{"en":"shake hands","ja":"握手する","lv":1,"ty":"動詞句","ex":"The two captains shook hands before the game started.","parts":["shook hands"],"exj":"試合が始まる前に、2人のキャプテンは握手した。","tip":"hands は複数形。shake hands with ～","ans":true,"dis":["come true","grow up","depend on","turn into","major in"],"set":1,"id":"p16"},{"en":"in a minute","ja":"すぐに","lv":1,"ty":"前置詞句・副詞句","ex":"Dinner will be ready in a minute, so please wash your hands.","parts":["in a minute"],"exj":"夕食はすぐできるから、手を洗ってね。","tip":"＝very soon。in a second も同じ","ans":true,"dis":["by mistake","by heart","in common","on business","in a word"],"set":1,"id":"p17"},{"en":"grow up","ja":"成長する・大人になる","lv":1,"ty":"動詞句","ex":"I grew up in a small town near the sea.","parts":["grew up"],"exj":"私は海の近くの小さな町で育った。","tip":"grown-up＝大人","ans":false,"dis":["come true","turn on","hope for","agree with","major in"],"set":1,"id":"p18"},{"en":"turn on","ja":"～をつける","lv":1,"ty":"動詞句","ex":"It was very hot, so I turned on the air conditioner.","parts":["turned on"],"exj":"とても暑かったので、エアコンをつけた。","tip":"反対は turn off（消す）","ans":false,"dis":["grow up","come true","agree with","depend on","major in"],"set":1,"id":"p19"},{"en":"belong to","ja":"～に属する・～のものだ","lv":1,"ty":"動詞句","ex":"This red umbrella belongs to my sister, so please give it back.","parts":["belongs to"],"exj":"この赤い傘は姉のものなので、返してください。","tip":"進行形にしない。belong to＋持ち主・団体","ans":false,"dis":["agree on","call out","show off","apply for","major in"],"set":2,"id":"p20"},{"en":"in advance","ja":"前もって・事前に","lv":2,"ty":"前置詞句・副詞句","ex":"Please buy your concert tickets in advance because they sell out fast.","parts":["in advance"],"exj":"チケットはすぐ売り切れるので、前もって買ってください。","tip":"pay in advance＝前払いする","ans":false,"dis":["by mistake","up to date","in common","out of date","in the old days"],"set":2,"id":"p21"},{"en":"by the end of","ja":"～の終わりまでに","lv":2,"ty":"前置詞句・副詞句","ex":"Please finish this homework by the end of the week.","parts":["by the end of"],"exj":"この宿題を週末までに終わらせてください。","tip":"by＝～までに（期限）。until＝～までずっと","ans":false,"dis":["at the sight of","in place of","by way of","for fear of","in the habit of"],"set":2,"id":"p22"},{"en":"on one's own","ja":"一人で・独力で","lv":2,"ty":"前置詞句・副詞句","ex":"My little brother can now ride his bike on his own.","parts":["on his own"],"exj":"弟は今では一人で自転車に乗れる。","tip":"＝by oneself。one's は my・his などに変わる","ans":true,"dis":["up to date","by heart","in common","out of date","by mistake"],"set":2,"id":"p23"},{"en":"up to date","ja":"最新の","lv":2,"ty":"前置詞句・副詞句","ex":"Our teacher keeps the class website up to date every week.","parts":["up to date"],"exj":"先生は毎週、クラスのウェブサイトを最新の状態にしている。","tip":"名詞の前では up-to-date。反対は out of date","ans":false,"dis":["in advance","by mistake","on business","in common","for long"],"set":2,"id":"p24"},{"en":"agree on","ja":"～について意見が一致する","lv":2,"ty":"動詞句","ex":"My family could not agree on where to go for summer vacation.","parts":["agree on"],"exj":"家族は夏休みにどこへ行くかで意見がまとまらなかった。","tip":"agree on＋決める事柄。agree with＋人・意見","ans":true,"dis":["belong to","show off","turn off","give off","major in"],"set":2,"id":"p25"},{"en":"call out","ja":"（～を）大声で呼ぶ・叫ぶ","lv":2,"ty":"動詞句","ex":"The teacher called out my name, so I stood up quickly.","parts":["called out"],"exj":"先生が私の名前を大声で呼んだので、すぐに立ち上がった。","tip":"call out to＋人＝人に大声で呼びかける","ans":false,"dis":["belong to","agree on","depend on","give off","run over"],"set":2,"id":"p26"},{"en":"at present","ja":"現在は・今のところ","lv":2,"ty":"前置詞句・副詞句","ex":"At present, my brother lives in Osaka, but he will move soon.","parts":["At present"],"exj":"兄は現在大阪に住んでいるが、もうすぐ引っ越す。","tip":"＝now。at the present time とも言う","ans":false,"dis":["in advance","up to date","by mistake","by heart","in common"],"set":2,"id":"p27"},{"en":"at the sight of","ja":"～を見て","lv":2,"ty":"前置詞句・副詞句","ex":"The little boy started to cry at the sight of the big dog.","parts":["at the sight of"],"exj":"その小さな男の子は大きな犬を見て泣き出した。","tip":"sight＝見ること。at first sight＝一目で","ans":false,"dis":["by the end of","in place of","in addition to","by way of","in terms of"],"set":2,"id":"p28"},{"en":"show off","ja":"～を見せびらかす","lv":2,"ty":"動詞句","ex":"Tom is always showing off his new smartphone to his friends.","parts":["showing off"],"exj":"トムはいつも友達に新しいスマホを見せびらかしている。","tip":"show-off（名詞）＝目立ちたがり屋","ans":false,"dis":["belong to","agree on","call out","depend on","major in"],"set":2,"id":"p29"},{"en":"in line","ja":"一列に並んで","lv":2,"ty":"前置詞句・副詞句","ex":"We waited in line for an hour to ride the roller coaster.","parts":["in line"],"exj":"私たちはジェットコースターに乗るために1時間列に並んで待った。","tip":"wait in line＝列に並んで待つ","ans":false,"dis":["on business","by heart","out of date","in common","in a word"],"set":3,"id":"p30"},{"en":"on business","ja":"仕事で・商用で","lv":2,"ty":"前置詞句・副詞句","ex":"My father often goes to Osaka on business, not for fun.","parts":["on business"],"exj":"父は遊びではなく、仕事でよく大阪へ行く。","tip":"反対は for pleasure（遊びで）","ans":true,"dis":["in line","by heart","up to date","in common","out of date"],"set":3,"id":"p31"},{"en":"do harm to","ja":"～に害を与える","lv":2,"ty":"動詞句","ex":"Eating too much sugar can do harm to your teeth.","parts":["do harm to"],"exj":"砂糖を取りすぎると歯に害を与えることがある。","tip":"↔do good to。harmful＝有害な","ans":false,"dis":["apply for","look up","get over","major in","wish for"],"set":3,"id":"p32"},{"en":"in place of","ja":"～の代わりに","lv":2,"ty":"前置詞句・副詞句","ex":"Our teacher was sick, so Mr. Brown taught our class in place of her.","parts":["in place of"],"exj":"先生が病気だったので、ブラウン先生が代わりに授業をした。","tip":"＝instead of。take the place of ～も同じ意味","ans":true,"dis":["at the sight of","by the end of","by way of","in terms of","for fear of"],"set":3,"id":"p33"},{"en":"for the moment","ja":"当面は・今のところ","lv":2,"ty":"前置詞句・副詞句","ex":"The rain has stopped for the moment, so let's go out now.","parts":["for the moment"],"exj":"雨が今のところやんだので、今のうちに出かけよう。","tip":"＝for now","ans":false,"dis":["in line","on business","on purpose","by heart","in common"],"set":3,"id":"p34"},{"en":"look up","ja":"～を調べる・見上げる","lv":2,"ty":"動詞句","ex":"If you don't know a word, look it up in your dictionary.","parts":["look","up"],"exj":"知らない単語があったら、辞書で調べなさい。","tip":"look ～ up＝（辞書で）調べる。it などは間に入る","ans":false,"dis":["give away","put off","turn down","see ~ off","hand over"],"set":3,"id":"p35"},{"en":"get over","ja":"～を乗り越える・～から回復する","lv":2,"ty":"動詞句","ex":"It took me two weeks to get over my bad cold.","parts":["get over"],"exj":"ひどいかぜが治るのに2週間かかった。","tip":"＝recover from","ans":false,"dis":["apply for","give away","look up","show off","major in"],"set":3,"id":"p36"},{"en":"give away","ja":"～をただであげる","lv":2,"ty":"動詞句","ex":"My aunt gave away her old books to the town library.","parts":["gave away"],"exj":"おばは古い本を町の図書館にあげた。","tip":"「秘密をもらす」の意味もある","ans":false,"dis":["look up","get over","apply for","agree on","suffer from"],"set":3,"id":"p37"},{"en":"apply for","ja":"～に応募する・申し込む","lv":2,"ty":"動詞句","ex":"My sister wants to apply for a part-time job at the new bookstore.","parts":["apply for"],"exj":"姉は新しい本屋のアルバイトに応募したがっている。","tip":"apply for＋仕事・奨学金。apply to＋会社・学校","ans":false,"dis":["get over","give away","do harm to","major in","run over"],"set":3,"id":"p38"},{"en":"on purpose","ja":"わざと・故意に","lv":2,"ty":"前置詞句・副詞句","ex":"My brother hid my shoes on purpose to make me late.","parts":["on purpose"],"exj":"弟は私を遅刻させようと、わざと私の靴を隠した。","tip":"反対は by accident（偶然に）","ans":true,"dis":["in line","on business","up to date","in common","by heart"],"set":3,"id":"p39"},{"en":"in the old days","ja":"昔は","lv":2,"ty":"前置詞句・副詞句","ex":"My grandmother says that in the old days, children played outside all day.","parts":["in the old days"],"exj":"祖母は、昔は子どもたちが一日中外で遊んでいたと言う。","tip":"＝long ago。今と比べて言うときに使う","ans":false,"dis":["by heart","in line","by mistake","up to date","on business"],"set":4,"id":"p40"},{"en":"pass by","ja":"（そばを）通り過ぎる","lv":2,"ty":"動詞句","ex":"I pass by the bakery every morning on my way to school.","parts":["pass by"],"exj":"私は毎朝、学校へ行く途中でそのパン屋の前を通る。","tip":"時が過ぎる意味も。Time passes by.","ans":false,"dis":["save up","major in","bring together","give off","suffer from"],"set":4,"id":"p41"},{"en":"save up","ja":"お金をためる","lv":2,"ty":"動詞句","ex":"I am saving up to buy a new bike next summer.","parts":["saving up"],"exj":"来年の夏に新しい自転車を買うためにお金をためている。","tip":"save up for ～＝～のためにお金をためる","ans":false,"dis":["major in","bring together","come across","go wrong","belong to"],"set":4,"id":"p42"},{"en":"take ~ seriously","ja":"～を真剣に受け止める","lv":2,"ty":"動詞句","ex":"You should take the doctor's advice seriously and stop eating sweets.","parts":["take","seriously"],"exj":"医者の助言を真剣に受け止めて、甘い物をやめるべきだ。","tip":"take it seriously＝本気にする・深刻に考える","ans":false,"dis":["see ~ off","call ~ up","give away","turn off","show off"],"set":4,"id":"p43"},{"en":"get through","ja":"～を乗り切る・終える","lv":2,"ty":"動詞句","ex":"I drank a lot of tea to get through the long night of studying.","parts":["get through"],"exj":"勉強の長い夜を乗り切るために、お茶をたくさん飲んだ。","tip":"「電話がつながる」の意味もある","ans":false,"dis":["save up","major in","apply for","show off","look like"],"set":4,"id":"p44"},{"en":"major in","ja":"～を専攻する","lv":2,"ty":"動詞句","ex":"My sister loves animals, so she is majoring in biology at college.","parts":["majoring in"],"exj":"姉は動物が大好きなので、大学で生物学を専攻している。","tip":"major は「専攻」（名詞）「主要な」の意味も","ans":false,"dis":["pass by","save up","bring together","turn off","show off"],"set":4,"id":"p45"},{"en":"bring together","ja":"～を集める・まとめる","lv":2,"ty":"動詞句","ex":"The school festival brings together students, parents, and teachers every fall.","parts":["brings together"],"exj":"文化祭は毎年秋、生徒・保護者・先生を一つに集める。","tip":"bring A and B together の形もある","ans":false,"dis":["save up","major in","get through","come across","give off"],"set":4,"id":"p46"},{"en":"come across","ja":"～に偶然出会う・見つける","lv":2,"ty":"動詞句","ex":"I came across an old photo of my grandfather while cleaning my room.","parts":["came across"],"exj":"部屋を掃除していて、祖父の古い写真を偶然見つけた。","tip":"＝run into（人に偶然会う）","ans":false,"dis":["save up","major in","bring together","apply for","suffer from"],"set":4,"id":"p47"},{"en":"go wrong","ja":"うまくいかない・故障する","lv":2,"ty":"動詞句","ex":"Our picnic plan went wrong when it suddenly started to snow.","parts":["went wrong"],"exj":"突然雪が降り出して、ピクニックの計画はうまくいかなかった。","tip":"What went wrong?＝何がまずかったの？","ans":true,"dis":["save up","pass by","grow up","calm down","sit up"],"set":4,"id":"p48"},{"en":"by heart","ja":"暗記して・そらで","lv":2,"ty":"前置詞句・副詞句","ex":"She practiced the speech many times, so now she knows it by heart.","parts":["by heart"],"exj":"彼女はスピーチを何度も練習したので、もう暗記している。","tip":"learn ～ by heart＝～を暗記する","ans":false,"dis":["in the old days","on business","in line","out of date","in common"],"set":4,"id":"p49"},{"en":"put off","ja":"～を延期する","lv":2,"ty":"動詞句","ex":"It rained on Saturday, so we put off the picnic until Sunday.","parts":["put off"],"exj":"土曜日は雨だったので、ピクニックを日曜日に延期した。","tip":"＝postpone。put off ～ing＝～するのを延ばす","ans":true,"dis":["dress up","run across","apply to","turn into","give off"],"set":5,"id":"p50"},{"en":"pay attention","ja":"注意を払う・よく聞く","lv":2,"ty":"動詞句","ex":"Drivers must pay attention to people crossing the street.","parts":["pay attention"],"exj":"運転手は道路を渡る人に注意を払わなければならない。","tip":"pay attention to ～＝～に注意を払う","ans":true,"dis":["dress up","put off","grow up","shake hands","major in"],"set":5,"id":"p51"},{"en":"be made up of","ja":"～で構成されている","lv":2,"ty":"動詞句","ex":"This salad is made up of tomatoes, cheese, and fresh lettuce.","parts":["made up of"],"exj":"このサラダはトマト、チーズ、新鮮なレタスでできている。","tip":"＝consist of。be composed of も同じ意味","ans":true,"dis":["be busy with","be on the point of","dress up","turn into","run across"],"set":5,"id":"p52"},{"en":"out of date","ja":"時代遅れの・古い","lv":2,"ty":"前置詞句・副詞句","ex":"This map is out of date, so it doesn't show the new station.","parts":["out of date"],"exj":"この地図は古いので、新しい駅がのっていない。","tip":"反対は up to date（最新の）","ans":false,"dis":["for the most part","in line","on business","by heart","in addition to"],"set":5,"id":"p53"},{"en":"for the most part","ja":"大部分は・たいてい","lv":2,"ty":"前置詞句・副詞句","ex":"The test was easy for the most part, but the last question was hard.","parts":["for the most part"],"exj":"テストは大部分は簡単だったが、最後の問題は難しかった。","tip":"＝mostly","ans":false,"dis":["out of date","in line","on business","by heart","up to date"],"set":5,"id":"p54"},{"en":"turn into","ja":"～に変わる・～になる","lv":2,"ty":"動詞句","ex":"When it gets very cold at night, the rain turns into snow.","parts":["turns into"],"exj":"夜にとても寒くなると、雨は雪に変わる。","tip":"A turn into B＝AがBに変わる","ans":true,"dis":["put off","dress up","run across","apply to","major in"],"set":5,"id":"p55"},{"en":"dress up","ja":"着飾る・仮装する","lv":2,"ty":"動詞句","ex":"Everyone dressed up as movie characters for the school festival.","parts":["dressed up"],"exj":"文化祭のために、みんな映画の登場人物の仮装をした。","tip":"dress up as ～＝～の仮装をする","ans":true,"dis":["pay attention","put off","apply to","run across","major in"],"set":5,"id":"p56"},{"en":"run across","ja":"～に偶然出会う","lv":2,"ty":"動詞句","ex":"I ran across an old friend from elementary school at the station yesterday.","parts":["ran across"],"exj":"昨日、駅で小学校の時の友達に偶然会った。","tip":"＝come across / run into","ans":true,"dis":["put off","apply to","turn into","major in","give off"],"set":5,"id":"p57"},{"en":"apply to","ja":"～に当てはまる・出願する","lv":2,"ty":"動詞句","ex":"This school rule applies to all students, even the third-year students.","parts":["applies to"],"exj":"この校則は3年生も含めて全生徒に当てはまる。","tip":"apply to＋学校＝～に出願する、の意味も","ans":false,"dis":["put off","dress up","turn into","run across","pay attention"],"set":5,"id":"p58"},{"en":"see ~ off","ja":"～を見送る","lv":2,"ty":"動詞句","ex":"My friends came to the bus terminal to see me off when I moved.","parts":["see","off"],"exj":"引っ越すとき、友達がバスターミナルまで見送りに来てくれた。","tip":"see ＋人＋ off。反対は meet（出迎える）","ans":true,"dis":["hand over","turn off","put away","turn over","pour out"],"set":5,"id":"p59"},{"en":"in addition to","ja":"～に加えて","lv":2,"ty":"前置詞句・副詞句","ex":"In addition to English, my cousin can speak Chinese and Korean.","parts":["In addition to"],"exj":"いとこは英語に加えて、中国語と韓国語も話せる。","tip":"in addition＝さらに（副詞）","ans":true,"dis":["at the sight of","by the end of","for fear of","by way of","in no time"],"set":6,"id":"p60"},{"en":"in no time","ja":"すぐに・あっという間に","lv":2,"ty":"前置詞句・副詞句","ex":"This new rice cooker is so fast that dinner was ready in no time.","parts":["in no time"],"exj":"この新しい炊飯器はとても速いので、夕食はあっという間にできた。","tip":"＝very quickly。no time＝時間ゼロで","ans":false,"dis":["in addition to","by heart","in line","on business","out of date"],"set":6,"id":"p61"},{"en":"give off","ja":"（におい・熱・光）を出す","lv":2,"ty":"動詞句","ex":"These white flowers give off a sweet smell in the evening.","parts":["give off"],"exj":"この白い花は夕方に甘い香りを放つ。","tip":"give off light／heat／smell","ans":false,"dis":["suffer from","rely on","figure out","turn down","major in"],"set":6,"id":"p62"},{"en":"suffer from","ja":"（病気など）に苦しむ","lv":2,"ty":"動詞句","ex":"My mother suffers from headaches when she doesn't sleep well.","parts":["suffers from"],"exj":"母はよく眠れないと頭痛に苦しむ。","tip":"suffer from a cold＝風邪をひいている","ans":true,"dis":["give off","rely on","figure out","turn down","show off"],"set":6,"id":"p63"},{"en":"break down","ja":"故障する","lv":2,"ty":"動詞句","ex":"Our car broke down on the highway, so we called for help.","parts":["broke down"],"exj":"車が高速道路で故障したので、助けを呼んだ。","tip":"人が主語だと「泣き崩れる」の意味も","ans":false,"dis":["make progress","come true","grow up","dress up","take turns"],"set":6,"id":"p64"},{"en":"make progress","ja":"進歩する・上達する","lv":2,"ty":"動詞句","ex":"Tom practices the piano every day, so he is making progress.","parts":["making progress"],"exj":"トムは毎日ピアノを練習しているので、上達している。","tip":"make progress in ～＝～が上達する。数えない名詞","ans":false,"dis":["suffer from","give off","rely on","figure out","turn down"],"set":6,"id":"p65"},{"en":"rely on","ja":"～に頼る・当てにする","lv":2,"ty":"動詞句","ex":"You can rely on Ken. He always keeps his promises.","parts":["rely on"],"exj":"ケンは頼りになるよ。いつも約束を守るから。","tip":"＝depend on / count on","ans":true,"dis":["suffer from","give off","turn down","run over","major in"],"set":6,"id":"p66"},{"en":"one another","ja":"お互い","lv":2,"ty":"その他","ex":"The students in my class often help one another with homework.","parts":["one another"],"exj":"私のクラスの生徒はよくお互いに宿題を助け合う。","tip":"＝each other。代名詞なので talk to one another","ans":true,"dis":["in addition to","in no time","in common","out of date","by heart"],"set":6,"id":"p67"},{"en":"turn down","ja":"～を断る・（音を）下げる","lv":2,"ty":"動詞句","ex":"Please turn down the TV. The baby is sleeping.","parts":["turn down"],"exj":"テレビの音を小さくして。赤ちゃんが寝ているの。","tip":"turn down an offer＝申し出を断る","ans":false,"dis":["rely on","suffer from","give off","break down","major in"],"set":6,"id":"p68"},{"en":"figure out","ja":"～を理解する・解き明かす","lv":2,"ty":"動詞句","ex":"Can you help me figure out how to use this new phone?","parts":["figure out"],"exj":"この新しい電話の使い方を理解するのを手伝ってくれる？","tip":"＝work out／understand","ans":true,"dis":["give off","suffer from","rely on","turn down","major in"],"set":6,"id":"p69"},{"en":"drop out of","ja":"～を中退する・～から抜ける","lv":2,"ty":"動詞句","ex":"He had to drop out of the race because he hurt his leg.","parts":["drop out of"],"exj":"彼は脚をけがしたので、レースを途中でやめなければならなかった。","tip":"dropout＝中退者","ans":false,"dis":["sit up","put up","major in","belong to","wish for"],"set":7,"id":"p70"},{"en":"do ~ good","ja":"～のためになる","lv":2,"ty":"動詞句","ex":"You look tired. A long walk in the park will do you good.","parts":["do","good"],"exj":"疲れているね。公園を長く散歩すると体にいいよ。","tip":"do＋人＋good の語順。harm の反対","ans":true,"dis":["see ~ off","call ~ up","learn ~ by heart","hand over","turn over"],"set":7,"id":"p71"},{"en":"set out","ja":"出発する・～を並べる","lv":2,"ty":"動詞句","ex":"We set out early in the morning to climb the mountain.","parts":["set out"],"exj":"私たちは山に登るため、朝早く出発した。","tip":"set out for ～＝～へ向けて出発する","ans":false,"dis":["break out","deal with","be short of","come true","major in"],"set":7,"id":"p72"},{"en":"learn ~ by heart","ja":"～を暗記する","lv":2,"ty":"動詞句","ex":"I had to learn the poem by heart for the English test.","parts":["learn","by heart"],"exj":"英語のテストのために、その詩を暗記しなければならなかった。","tip":"＝memorize。learn ＋もの＋ by heart の語順","ans":false,"dis":["see ~ off","call ~ up","do ~ good","turn off","give away"],"set":7,"id":"p73"},{"en":"sit up","ja":"背筋を伸ばして座る・起きている","lv":2,"ty":"動詞句","ex":"Please sit up straight when you are writing at your desk.","parts":["sit up"],"exj":"机で字を書くときは、背筋を伸ばして座りなさい。","tip":"sit up late＝夜ふかしする","ans":false,"dis":["break out","come true","deal with","belong to","major in"],"set":7,"id":"p74"},{"en":"be short of","ja":"～が不足している","lv":2,"ty":"動詞句","ex":"We are short of money, so we can't buy a new car.","parts":["short of"],"exj":"お金が足りないので、新しい車は買えない。","tip":"run short of ～＝～が足りなくなる","ans":true,"dis":["be busy with","be made up of","be on the point of","deal with","put up"],"set":7,"id":"p75"},{"en":"deal with","ja":"～に対処する・～を扱う","lv":2,"ty":"動詞句","ex":"Our teacher knows how to deal with problems between classmates.","parts":["deal with"],"exj":"先生はクラスメート同士の問題にどう対処すればよいか分かっている。","tip":"deal-dealt-dealt。＝handle","ans":true,"dis":["set out","sit up","break out","come true","give off"],"set":7,"id":"p76"},{"en":"put up","ja":"～を掲げる・建てる","lv":2,"ty":"動詞句","ex":"We put up a poster about the school festival in the hall.","parts":["put up"],"exj":"私たちは廊下に文化祭のポスターを貼った。","tip":"put up with ～＝～をがまんする","ans":false,"dis":["sit up","break out","suffer from","run over","get over"],"set":7,"id":"p77"},{"en":"in the way","ja":"じゃまになって","lv":2,"ty":"前置詞句・副詞句","ex":"Your big bag is in the way, so I can't open the door.","parts":["in the way"],"exj":"あなたの大きなかばんがじゃまで、ドアが開けられない。","tip":"get in the way＝じゃまをする。by the way と区別","ans":false,"dis":["by heart","on business","out of date","in a word","for nothing"],"set":7,"id":"p78"},{"en":"break out","ja":"（火事・戦争が）起こる","lv":2,"ty":"動詞句","ex":"A fire broke out in the kitchen, but everyone got out safely.","parts":["broke out"],"exj":"台所で火事が起きたが、全員無事に外へ出た。","tip":"突然起こるときに使う。outbreak＝発生","ans":false,"dis":["set out","sit up","deal with","put up","major in"],"set":7,"id":"p79"},{"en":"take turns","ja":"交代でする","lv":2,"ty":"動詞句","ex":"There is only one swing, so the children take turns riding it.","parts":["take turns"],"exj":"ブランコが1つしかないので、子どもたちは交代で乗る。","tip":"take turns ～ing＝交代で～する","ans":true,"dis":["take place","turn in","pass around","make sense","major in"],"set":8,"id":"p80"},{"en":"in a word","ja":"一言で言えば","lv":2,"ty":"前置詞句・副詞句","ex":"In a word, the trip was perfect, and we want to go again.","parts":["In a word"],"exj":"一言で言えば旅行は最高で、また行きたい。","tip":"＝in short（要するに）","ans":false,"dis":["in good shape","by mistake","in line","by heart","out of date"],"set":8,"id":"p81"},{"en":"exchange A for B","ja":"AをBと交換・両替する","lv":2,"ty":"動詞句","ex":"Can I exchange this shirt for a bigger size at this store?","parts":["exchange","for"],"exj":"この店で、このシャツを大きいサイズと交換できますか。","tip":"両替にも使う。exchange dollars for yen","ans":true,"dis":["take ~ seriously","see ~ off","call ~ up","learn ~ by heart","turn in"],"set":8,"id":"p82"},{"en":"in good shape","ja":"体調がよい・よい状態で","lv":2,"ty":"前置詞句・副詞句","ex":"My grandfather walks every morning to stay in good shape.","parts":["in good shape"],"exj":"祖父は体調を保つために毎朝歩いている。","tip":"keep in shape＝体調を保つ。反対は out of shape","ans":true,"dis":["in a word","all of a sudden","by mistake","on business","in common"],"set":8,"id":"p83"},{"en":"all of a sudden","ja":"突然・不意に","lv":2,"ty":"前置詞句・副詞句","ex":"We were playing soccer, and all of a sudden it started to rain.","parts":["all of a sudden"],"exj":"サッカーをしていたら、突然雨が降り出した。","tip":"＝suddenly。文頭にも置ける","ans":true,"dis":["in good shape","in a word","by heart","in common","out of date"],"set":8,"id":"p84"},{"en":"take place","ja":"行われる・起こる","lv":2,"ty":"動詞句","ex":"The final game will take place at the city stadium on Sunday.","parts":["take place"],"exj":"決勝戦は日曜日に市の競技場で行われる。","tip":"＝be held。受け身にしない","ans":true,"dis":["turn in","get rid of","take turns","make sense","major in"],"set":8,"id":"p85"},{"en":"turn in","ja":"～を提出する","lv":2,"ty":"動詞句","ex":"Don't forget to turn in your homework by Friday.","parts":["turn in"],"exj":"金曜日までに宿題を提出するのを忘れないで。","tip":"＝hand in / submit","ans":false,"dis":["take place","get rid of","take turns","turn out","run over"],"set":8,"id":"p86"},{"en":"get rid of","ja":"～を取り除く・処分する","lv":2,"ty":"動詞句","ex":"We got rid of our old sofa and bought a new one.","parts":["got rid of"],"exj":"私たちは古いソファを処分して、新しいのを買った。","tip":"rid は過去形も rid。不要な物を捨てる","ans":false,"dis":["take place","take turns","pass around","make sense","suffer from"],"set":8,"id":"p87"},{"en":"pass around","ja":"～を順に回す・配る","lv":2,"ty":"動詞句","ex":"The teacher passed around the photos so everyone could see them.","parts":["passed around"],"exj":"全員が見られるように、先生は写真を回した。","tip":"人から人へ順に回す。hand out＝配る","ans":false,"dis":["take place","take turns","make sense","suffer from","run over"],"set":8,"id":"p88"},{"en":"turn out","ja":"～だとわかる・結局～になる","lv":2,"ty":"動詞句","ex":"We were worried about the party, but it turned out well.","parts":["turned out"],"exj":"パーティーが心配だったが、結局うまくいった。","tip":"turn out to be ～＝～だとわかる","ans":false,"dis":["take turns","turn in","get rid of","pass around","major in"],"set":8,"id":"p89"},{"en":"move on","ja":"次へ進む","lv":2,"ty":"動詞句","ex":"We have finished page ten, so let's move on to the next page.","parts":["move on"],"exj":"10ページが終わったので、次のページに進みましょう。","tip":"move on to ～＝～に移る","ans":false,"dis":["make sense","wish for","hold up","shake hands","belong to"],"set":9,"id":"p90"},{"en":"for nothing","ja":"無料で・無駄に","lv":2,"ty":"前置詞句・副詞句","ex":"The shop gave us this tote bag for nothing when we bought shoes.","parts":["for nothing"],"exj":"靴を買ったら、店がこのトートバッグを無料でくれた。","tip":"①無料で（＝for free）②無駄に","ans":false,"dis":["in the way","by heart","in common","out of date","in a word"],"set":9,"id":"p91"},{"en":"put away","ja":"～を片付ける・しまう","lv":2,"ty":"動詞句","ex":"After playing, please put away your toys in the box.","parts":["put away"],"exj":"遊んだ後は、おもちゃを箱に片付けてね。","tip":"put ～ away＝～をしまう。it などは間に入る","ans":true,"dis":["wish for","catch up with","make sense","give off","major in"],"set":9,"id":"p92"},{"en":"catch up with","ja":"～に追いつく","lv":2,"ty":"動詞句","ex":"I ran fast to catch up with my friends on the way to school.","parts":["catch up with"],"exj":"登校中、友達に追いつこうと速く走った。","tip":"keep up with＝遅れずについていく","ans":true,"dis":["put away","wish for","make sense","belong to","major in"],"set":9,"id":"p93"},{"en":"hold up","ja":"～を持ち上げる・遅らせる","lv":2,"ty":"動詞句","ex":"Please hold up your hand if you know the answer.","parts":["hold up"],"exj":"答えが分かったら手を挙げてください。","tip":"be held up＝（渋滞などで）遅れる","ans":false,"dis":["put away","catch up with","wish for","make sense","get rid of"],"set":9,"id":"p94"},{"en":"on one's side","ja":"～の味方で","lv":2,"ty":"前置詞句・副詞句","ex":"Don't worry. Your family will always be on your side.","parts":["on your side"],"exj":"心配しないで。家族はいつもあなたの味方だよ。","tip":"be on ～'s side＝～の味方だ","ans":false,"dis":["for nothing","out of date","in a word","by heart","by mistake"],"set":9,"id":"p95"},{"en":"wish for","ja":"～を願う・望む","lv":2,"ty":"動詞句","ex":"On her birthday, Lisa blew out the candles and wished for a puppy.","parts":["wished for"],"exj":"誕生日に、リサはろうそくを吹き消して子犬がほしいと願った。","tip":"wish for ＋名詞。wish to ＋動詞の原形","ans":false,"dis":["put away","catch up with","make sense","give off","major in"],"set":9,"id":"p96"},{"en":"make sense","ja":"意味が通じる・理にかなう","lv":2,"ty":"動詞句","ex":"Your story doesn't make sense. Please tell me again slowly.","parts":["make sense"],"exj":"あなたの話は意味が通じない。もう一度ゆっくり話して。","tip":"make sense of ～＝～を理解する","ans":false,"dis":["wish for","put away","catch up with","shake hands","grow up"],"set":9,"id":"p97"},{"en":"hold back","ja":"～を抑える・こらえる","lv":2,"ty":"動詞句","ex":"She tried to hold back her tears when her friend moved away.","parts":["hold back"],"exj":"友達が引っ越すとき、彼女は涙をこらえようとした。","tip":"hold back tears＝涙をこらえる","ans":false,"dis":["wish for","catch up with","make sense","give off","apply for"],"set":9,"id":"p98"},{"en":"turn over","ja":"～をひっくり返す","lv":2,"ty":"動詞句","ex":"Cook the pancake for two minutes, then turn it over.","parts":["turn","over"],"exj":"パンケーキを2分焼いてから、ひっくり返してください。","tip":"turn over the page＝ページをめくる","ans":false,"dis":["see ~ off","call ~ up","take ~ seriously","learn ~ by heart","do ~ good"],"set":9,"id":"p99"},{"en":"in common","ja":"共通して","lv":2,"ty":"前置詞句・副詞句","ex":"My best friend and I have a lot in common, like music and sports.","parts":["in common"],"exj":"親友と私は、音楽やスポーツなど共通点がたくさんある。","tip":"have ～ in common＝～を共通に持つ","ans":true,"dis":["by any chance","by mistake","in line","out of date","on business"],"set":10,"id":"p100"},{"en":"back up","ja":"～を裏付ける・支持する","lv":2,"ty":"動詞句","ex":"In your essay, you need to back up your opinion with good reasons.","parts":["back up"],"exj":"作文では、意見をしっかりした理由で裏付ける必要がある。","tip":"データの「バックアップ」も同じ back up","ans":true,"dis":["take over","take it easy","give off","run over","turn off"],"set":10,"id":"p101"},{"en":"take over","ja":"～を引き継ぐ","lv":2,"ty":"動詞句","ex":"When Mr. Sato retired, his son took over the family shop.","parts":["took over"],"exj":"佐藤さんが引退したとき、息子が家の店を引き継いだ。","tip":"take over A from B＝BからAを引き継ぐ","ans":false,"dis":["back up","suffer from","give off","run over","look like"],"set":10,"id":"p102"},{"en":"take it easy","ja":"気楽にやる・のんびりする","lv":2,"ty":"動詞句","ex":"You worked hard all week, so take it easy this weekend.","parts":["take it easy"],"exj":"一週間がんばったから、今週末はのんびりしてね。","tip":"別れぎわの「じゃあね」の意味もある","ans":true,"dis":["hand over","come true","break out","take place","give way"],"set":10,"id":"p103"},{"en":"by the time","ja":"～する時までには","lv":2,"ty":"その他","ex":"By the time we got to the station, the train had already left.","parts":["By the time"],"exj":"私たちが駅に着いた時には、電車はもう出ていた。","tip":"後ろに主語＋動詞が続く（接続詞の働き）","ans":false,"dis":["every other","by any chance","in a word","for nothing","out of date"],"set":10,"id":"p104"},{"en":"every other","ja":"1つおきの","lv":2,"ty":"その他","ex":"I go swimming every other day: Monday, Wednesday, and Friday.","parts":["every other"],"exj":"私は1日おきに泳ぎに行く。月・水・金だ。","tip":"every other day＝1日おきに","ans":false,"dis":["by the time","by any chance","in common","in line","on business"],"set":10,"id":"p105"},{"en":"hand over","ja":"～を手渡す・引き渡す","lv":2,"ty":"動詞句","ex":"Please hand over your phones to the teacher before the test starts.","parts":["hand over"],"exj":"テストが始まる前に、携帯電話を先生に渡してください。","tip":"hand in（提出する）と区別しよう","ans":false,"dis":["back up","take over","keep up","look like","run over"],"set":10,"id":"p106"},{"en":"by any chance","ja":"ひょっとして・もしかして","lv":2,"ty":"前置詞句・副詞句","ex":"Are you Ken's sister, by any chance? You look just like him.","parts":["by any chance"],"exj":"もしかしてケンのお姉さん？そっくりですね。","tip":"疑問文で丁寧にたずねるときに使う","ans":false,"dis":["in common","every other","on business","by heart","out of date"],"set":10,"id":"p107"},{"en":"call ~ up","ja":"～に電話をかける","lv":2,"ty":"動詞句","ex":"I will call you up when I get home tonight.","parts":["call","up"],"exj":"今夜家に着いたら、あなたに電話するね。","tip":"call＋人＋up の語順。＝call／phone","ans":false,"dis":["hand over","take over","learn ~ by heart","put away","pour out"],"set":10,"id":"p108"},{"en":"keep up","ja":"ついていく・～を続ける","lv":2,"ty":"動詞句","ex":"Ken walks so fast that I can't keep up with him.","parts":["keep up"],"exj":"ケンは歩くのがとても速いので、私はついていけない。","tip":"keep up with ～＝～に遅れずについていく","ans":false,"dis":["back up","take over","hand over","major in","give off"],"set":10,"id":"p109"},{"en":"carry on","ja":"（～を）続ける","lv":2,"ty":"動詞句","ex":"Please carry on with your work while I answer the phone.","parts":["carry on"],"exj":"私が電話に出ている間、作業を続けてください。","tip":"carry on with ～／carry on ～ing＝～を続ける","ans":false,"dis":["take after","give way","lay out","shake hands","major in"],"set":11,"id":"p110"},{"en":"take action","ja":"行動を起こす","lv":2,"ty":"動詞句","ex":"We must take action now to keep our beach clean.","parts":["take action"],"exj":"海辺をきれいに保つために、今すぐ行動を起こさなければならない。","tip":"take action against ～＝～に対策をとる","ans":true,"dis":["take after","come down with","give way","grow up","come true"],"set":11,"id":"p111"},{"en":"in order to","ja":"～するために","lv":2,"ty":"その他","ex":"She got up early in order to catch the first train.","parts":["in order to"],"exj":"彼女は始発電車に乗るために早起きした。","tip":"in order not to ～＝～しないように","ans":true,"dis":["with care","for good","for fear of","in place of","by way of"],"set":11,"id":"p112"},{"en":"take after","ja":"（親など）に似ている","lv":2,"ty":"動詞句","ex":"Emma takes after her father. They both have curly hair.","parts":["takes after"],"exj":"エマは父親似だ。2人とも巻き毛だ。","tip":"親や親族に似ている。＝resemble","ans":false,"dis":["carry on","take action","lay out","come down with","apply for"],"set":11,"id":"p113"},{"en":"with care","ja":"注意して・慎重に","lv":2,"ty":"前置詞句・副詞句","ex":"These glasses break easily, so please carry them with care.","parts":["with care"],"exj":"このグラスは割れやすいので、注意して運んでください。","tip":"＝carefully。Handle with care＝取扱注意","ans":false,"dis":["for good","by heart","out of date","in common","in a word"],"set":11,"id":"p114"},{"en":"give way","ja":"崩れる・（～に）譲る","lv":3,"ty":"動詞句","ex":"The old wooden bridge gave way under the heavy snow last winter.","parts":["gave way"],"exj":"その古い木の橋は、去年の冬に大雪で崩れた。","tip":"give way to ～＝～に道を譲る・負ける","ans":false,"dis":["take action","take after","come of age","give applause","major in"],"set":11,"id":"p115"},{"en":"come down with","ja":"（病気）にかかる","lv":3,"ty":"動詞句","ex":"Mika came down with a fever, so she stayed home from school.","parts":["came down with"],"exj":"ミカは熱を出したので、学校を休んだ。","tip":"come down with a cold＝かぜをひく","ans":false,"dis":["take after","lay out","stand by","show off","apply for"],"set":11,"id":"p116"},{"en":"lay out","ja":"～を並べる・広げる","lv":3,"ty":"動詞句","ex":"Mom laid out the plates and forks on the table before dinner.","parts":["laid out"],"exj":"母は夕食の前に、テーブルに皿とフォークを並べた。","tip":"lay の過去形は laid。lie（横になる）と区別","ans":false,"dis":["take after","come down with","stand by","suffer from","major in"],"set":11,"id":"p117"},{"en":"for good","ja":"永久に・これを最後に","lv":3,"ty":"前置詞句・副詞句","ex":"My best friend is moving to Canada for good, so I feel sad.","parts":["for good"],"exj":"親友がカナダにずっと住むために引っ越すので、悲しい。","tip":"＝forever。「よい」の意味ではない","ans":false,"dis":["with care","in order to","by heart","in common","in a word"],"set":11,"id":"p118"},{"en":"stand by","ja":"～を支える・待機する","lv":3,"ty":"動詞句","ex":"Good friends will always stand by you when you are in trouble.","parts":["stand by"],"exj":"困ったとき、よい友達はいつもあなたを支えてくれる。","tip":"stand by ～＝～の味方をする／待機する","ans":false,"dis":["take after","lay out","come down with","give off","major in"],"set":11,"id":"p119"},{"en":"have faith","ja":"（～を）信じる・信頼する","lv":3,"ty":"動詞句","ex":"Have faith in yourself, and you will do well in the game.","parts":["Have faith"],"exj":"自分を信じなさい。そうすれば試合でうまくいく。","tip":"have faith in ～＝～を信じる","ans":false,"dis":["give applause","come of age","take turns","shake hands","take place"],"set":12,"id":"p120"},{"en":"give in to","ja":"～に屈する・負ける","lv":3,"ty":"動詞句","ex":"Even when my little brother cries, my mom does not give in to him.","parts":["give in to"],"exj":"弟が泣いても、母は言いなりにならない。","tip":"give in＝降参する。＝yield to","ans":false,"dis":["come of age","apply for","major in","run over","give off"],"set":12,"id":"p121"},{"en":"find fault","ja":"（～の）あら探しをする","lv":3,"ty":"動詞句","ex":"My aunt always finds fault with my clothes, and it makes me sad.","parts":["finds fault"],"exj":"おばはいつも私の服にけちをつけるので、悲しくなる。","tip":"find fault with ～＝～にけちをつける","ans":true,"dis":["have faith","come of age","take turns","take place","major in"],"set":12,"id":"p122"},{"en":"come of age","ja":"成人する","lv":3,"ty":"動詞句","ex":"My sister will come of age next year when she turns eighteen.","parts":["come of age"],"exj":"姉は来年18歳になって成人する。","tip":"coming-of-age ceremony＝成人式","ans":false,"dis":["find fault","have faith","give applause","take turns","break out"],"set":12,"id":"p123"},{"en":"for fear of","ja":"～を恐れて","lv":3,"ty":"前置詞句・副詞句","ex":"She walked slowly on the ice for fear of falling down.","parts":["for fear of"],"exj":"彼女は転ぶのを恐れて、氷の上をゆっくり歩いた。","tip":"for fear of ～ing＝～しないように","ans":false,"dis":["in terms of","on behalf of","by way of","in place of","by the end of"],"set":12,"id":"p124"},{"en":"at length","ja":"詳しく・長々と・ついに","lv":3,"ty":"前置詞句・副詞句","ex":"The teacher explained the new rules at length, so the class ended late.","parts":["at length"],"exj":"先生が新しい規則を長々と説明したので、授業が遅く終わった。","tip":"①詳しく長々と ②ついに（＝at last）","ans":false,"dis":["from day to day","for good","by heart","out of date","in common"],"set":12,"id":"p125"},{"en":"in terms of","ja":"～の点で・～に関して","lv":3,"ty":"前置詞句・副詞句","ex":"This phone is the best in terms of price, but its camera is poor.","parts":["in terms of"],"exj":"この電話は値段の点では一番だが、カメラはよくない。","tip":"in terms of cost＝費用の点では","ans":false,"dis":["for fear of","on behalf of","by way of","at the sight of","in place of"],"set":12,"id":"p126"},{"en":"from day to day","ja":"日ごとに・日々","lv":3,"ty":"前置詞句・副詞句","ex":"The weather in spring changes from day to day, so take a jacket.","parts":["from day to day"],"exj":"春の天気は日ごとに変わるので、上着を持っていきなさい。","tip":"day by day（日に日に）と似ている","ans":false,"dis":["for fear of","on behalf of","by heart","on business","in common"],"set":12,"id":"p127"},{"en":"on behalf of","ja":"～を代表して・～の代わりに","lv":3,"ty":"前置詞句・副詞句","ex":"The captain thanked the coach on behalf of the whole team.","parts":["on behalf of"],"exj":"キャプテンはチーム全体を代表してコーチにお礼を言った。","tip":"on behalf of ～＝～を代表して","ans":false,"dis":["by way of","for fear of","by the end of","in the habit of","at fault"],"set":12,"id":"p128"},{"en":"by way of","ja":"～経由で","lv":3,"ty":"前置詞句・副詞句","ex":"We flew to London by way of Dubai because the ticket was cheaper.","parts":["by way of"],"exj":"チケットが安かったので、ドバイ経由でロンドンへ飛んだ。","tip":"＝via。「～として」の意味もある","ans":false,"dis":["on behalf of","in terms of","in the habit of","at the sight of","for fear of"],"set":12,"id":"p129"},{"en":"with regard to","ja":"～に関して","lv":3,"ty":"前置詞句・副詞句","ex":"I have a question with regard to tomorrow's school trip.","parts":["with regard to"],"exj":"明日の遠足に関して質問があります。","tip":"＝about / regarding。書き言葉でよく使う","ans":false,"dis":["by means of","in the habit of","for fear of","by way of","on behalf of"],"set":13,"id":"p130"},{"en":"pull away","ja":"（車が）走り去る・離れる","lv":3,"ty":"動詞句","ex":"The bus pulled away just as I got to the bus stop.","parts":["pulled away"],"exj":"私がバス停に着いたちょうどそのとき、バスが走り去った。","tip":"pull away from ～＝～から離れる","ans":false,"dis":["make out","pour out","come true","give applause","grow up"],"set":13,"id":"p131"},{"en":"make out","ja":"～を見分ける・理解する","lv":3,"ty":"動詞句","ex":"The sign was so far away that I couldn't make out the words.","parts":["make out"],"exj":"看板がとても遠かったので、文字が見分けられなかった。","tip":"can't make out ～＝～がよく見えない・分からない","ans":true,"dis":["pour out","pull away","give off","run over","major in"],"set":13,"id":"p132"},{"en":"on hand","ja":"手元に・用意して","lv":3,"ty":"前置詞句・副詞句","ex":"Always keep some water on hand in case of an earthquake.","parts":["on hand"],"exj":"地震に備えて、いつも水を手元に置いておきなさい。","tip":"have ～ on hand＝～を手元に持っている","ans":false,"dis":["at fault","in a word","by heart","on business","in common"],"set":13,"id":"p133"},{"en":"pour out","ja":"～を注ぎ出す・打ち明ける","lv":3,"ty":"動詞句","ex":"Dad poured out the old milk because it smelled bad.","parts":["poured out"],"exj":"古い牛乳が嫌なにおいだったので、父はそれを流して捨てた。","tip":"pour out one's heart＝胸の内を打ち明ける","ans":false,"dis":["make out","take after","give applause","major in","apply for"],"set":13,"id":"p134"},{"en":"in the habit of","ja":"～する習慣があって","lv":3,"ty":"前置詞句・副詞句","ex":"My father is in the habit of reading the newspaper after breakfast.","parts":["in the habit of"],"exj":"父は朝食後に新聞を読む習慣がある。","tip":"be in the habit of ～ing＝～する習慣がある","ans":false,"dis":["by means of","with regard to","on behalf of","for fear of","in place of"],"set":13,"id":"p135"},{"en":"be on the point of","ja":"まさに～しようとして","lv":3,"ty":"動詞句","ex":"I was on the point of leaving home when it started to rain.","parts":["on the point of"],"exj":"ちょうど家を出ようとしたとき、雨が降り始めた。","tip":"be on the point of ～ing＝be about to ～","ans":true,"dis":["be short of","be filled with","be made up of","make out","keep back"],"set":13,"id":"p136"},{"en":"at fault","ja":"（～に）責任がある・悪い","lv":3,"ty":"前置詞句・副詞句","ex":"The police said the other driver was at fault for the accident.","parts":["at fault"],"exj":"警察は、事故の責任は相手の運転手にあると言った。","tip":"be at fault＝（事故などで）悪いのは～だ","ans":false,"dis":["in the habit of","by means of","by heart","in common","out of date"],"set":13,"id":"p137"},{"en":"by means of","ja":"～によって・～を使って","lv":3,"ty":"前置詞句・副詞句","ex":"My grandparents talk with us by means of video calls every Sunday.","parts":["by means of"],"exj":"祖父母は毎週日曜にビデオ通話で私たちと話す。","tip":"means＝手段（単数も複数も means）","ans":false,"dis":["in the habit of","for fear of","at the sight of","by the end of","at fault"],"set":13,"id":"p138"},{"en":"keep back","ja":"下がっている・～を抑える","lv":3,"ty":"動詞句","ex":"The police told the crowd to keep back from the burning house.","parts":["keep back"],"exj":"警察は群衆に、燃えている家から離れているように言った。","tip":"keep back tears＝涙をこらえる","ans":false,"dis":["make out","pour out","come true","give applause","major in"],"set":13,"id":"p139"},{"en":"take in","ja":"～を理解する・取り入れる","lv":3,"ty":"動詞句","ex":"The teacher spoke so fast that I couldn't take in everything.","parts":["take in"],"exj":"先生の話がとても速くて、全部は理解できなかった。","tip":"be taken in＝だまされる","ans":false,"dis":["give applause","hold out","run over","give off","shake hands"],"set":14,"id":"p140"},{"en":"give applause","ja":"拍手を送る","lv":3,"ty":"動詞句","ex":"Everyone stood up and gave applause to the brave firefighters.","parts":["gave applause"],"exj":"みんな立ち上がって、勇敢な消防士たちに拍手を送った。","tip":"applause＝拍手（数えない）。applaud＝拍手する","ans":false,"dis":["take in","get away with","run over","come down with","major in"],"set":14,"id":"p141"},{"en":"with any luck","ja":"うまくいけば","lv":3,"ty":"前置詞句・副詞句","ex":"We left home early, so with any luck we will get good seats.","parts":["with any luck"],"exj":"早く家を出たので、うまくいけばいい席がとれるだろう。","tip":"＝if we are lucky。運がよければ","ans":false,"dis":["out of the question","by heart","on business","out of date","in common"],"set":14,"id":"p142"},{"en":"hold out","ja":"～を差し出す・持ちこたえる","lv":3,"ty":"動詞句","ex":"The boy held out his hand to help me stand up.","parts":["held out"],"exj":"男の子は私が立ち上がれるよう手を差し出してくれた。","tip":"hold out one's hand＝手を差し出す","ans":false,"dis":["take in","give applause","get away with","run over","come down with"],"set":14,"id":"p143"},{"en":"out of the question","ja":"問題外で・ありえない","lv":3,"ty":"前置詞句・副詞句","ex":"Going to the beach in this big storm is out of the question.","parts":["out of the question"],"exj":"この大嵐の中で海に行くなんて問題外だ。","tip":"＝impossible。the を忘れずに","ans":true,"dis":["with ease","with any luck","by heart","on business","in common"],"set":14,"id":"p144"},{"en":"get away with","ja":"（悪事を）罰を受けずに済ます","lv":3,"ty":"動詞句","ex":"He cheated on the test, but he did not get away with it.","parts":["get away with"],"exj":"彼はテストでカンニングしたが、ばれずには済まなかった。","tip":"get away＝逃げる。悪いことについて使う","ans":false,"dis":["take in","hold out","run over","give applause","major in"],"set":14,"id":"p145"},{"en":"with ease","ja":"簡単に・楽々と","lv":3,"ty":"前置詞句・副詞句","ex":"Tom is so strong that he lifted the heavy box with ease.","parts":["with ease"],"exj":"トムはとても力が強いので、重い箱を楽々と持ち上げた。","tip":"＝easily。without difficulty も同じ","ans":false,"dis":["out of the question","on account of","by heart","in common","out of date"],"set":14,"id":"p146"},{"en":"run over","ja":"（車が）～をひく","lv":3,"ty":"動詞句","ex":"Be careful! That car almost ran over the cat on the road.","parts":["ran over"],"exj":"気をつけて！あの車が道にいたネコをひきそうになった。","tip":"be run over by a car＝車にひかれる","ans":false,"dis":["take in","give applause","hold out","get away with","major in"],"set":14,"id":"p147"},{"en":"at any cost","ja":"どんな犠牲を払っても","lv":3,"ty":"前置詞句・副詞句","ex":"He wanted to win the race at any cost, so he practiced every day.","parts":["at any cost"],"exj":"彼は何としてもレースに勝ちたくて、毎日練習した。","tip":"＝at all costs。何としても","ans":false,"dis":["out of the question","by heart","in common","out of date","on business"],"set":14,"id":"p148"},{"en":"by all means","ja":"ぜひどうぞ・必ず","lv":3,"ty":"前置詞句・副詞句","ex":"\"Can I borrow your eraser?\" \"By all means. Here you are.\"","parts":["By all means"],"exj":"「消しゴムを借りていい？」「どうぞどうぞ。はい。」","tip":"許可を求められて「どうぞ」と答える表現","ans":false,"dis":["on account of","with ease","in common","out of date","by heart"],"set":14,"id":"p149"},{"en":"on account of","ja":"～のために（理由）","lv":3,"ty":"前置詞句・副詞句","ex":"The baseball game was canceled on account of the heavy rain.","parts":["on account of"],"exj":"野球の試合は大雨のために中止になった。","tip":"＝because of。後ろは名詞","ans":false,"dis":["on behalf of","by way of","in the habit of","by the end of","at the sight of"],"set":14,"id":"p150"}];
